package com.metabuild.modules.admin.roles.application;
import com.metabuild.modules.admin.auth.api.AuthorizationRefreshService; import java.util.*;
public final class RoleService {private final RoleRepository roles;private final AuthorizationRefreshService refresh;public RoleService(RoleRepository r,AuthorizationRefreshService f){roles=r;refresh=f;}public List<RoleView> list(){return roles.list();}public RoleView detail(UUID id){return roles.find(id).orElseThrow(()->new com.metabuild.shared.kernel.NotFound(()->"iam.role.not-found","Role not found"));}public List<RoleRepository.RoleMember> members(UUID id){detail(id);return roles.memberViews(id);}public List<RoleRepository.PermissionGroup> permissionTree(){return roles.permissionTree();}public List<RoleRepository.RoleAuditLog> auditLogs(){return roles.auditLogs();}public Map<String,Set<String>> permissions(UUID id){detail(id);return roles.permissions(id);}public RoleRepository.DataScopeGrant dataScope(UUID id){detail(id);return roles.dataScope(id);}public RoleView create(UUID id,String n,String d){return roles.create(id,n,d==null?"":d);}public RoleView update(UUID id,String n,String d){return refresh.execute(AuthorizationRefreshService.Cause.ROLE_CHANGED,change(id,()->roles.update(id,n,d)));}public void delete(UUID id){refresh.execute(AuthorizationRefreshService.Cause.ROLE_CHANGED,change(id,()->{roles.delete(id);return null;}));}public void disable(UUID id){refresh.execute(AuthorizationRefreshService.Cause.ROLE_CHANGED,change(id,()->{roles.disable(id);return null;}));}public Map<String,Set<String>> grant(UUID id,Map<String,Set<String>> grants){return refresh.execute(AuthorizationRefreshService.Cause.GRANT_CHANGED,change(id,()->{roles.replacePermissions(id,grants);return roles.permissions(id);}));}public RoleRepository.DataScopeGrant scope(UUID id,RoleRepository.DataScope s,Set<UUID> depts){return refresh.execute(AuthorizationRefreshService.Cause.DATA_SCOPE_CHANGED,change(id,()->{roles.replaceDataScope(id,s,depts);return roles.dataScope(id);}));}private <T> AuthorizationRefreshService.AuthorizationChange<T> change(UUID role,java.util.function.Supplier<T> mutation){return new AuthorizationRefreshService.AuthorizationChange<>(){public Set<UUID> affectedUserIds(){return roles.members(role);}public T mutate(){return mutation.get();}};}}
